import { test, expect } from 'bun:test';
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  writeFileSync,
  rmSync,
  mkdirSync,
  symlinkSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { adopt } from '../lib/adopt.mjs';
import { ROOT, copySnapshot } from '../lib/lifecycle.mjs';

function fixture(packageValue: unknown = { name: 'existing-app', private: true }) {
  const temp = mkdtempSync(join(tmpdir(), 'garden-adopt-'));
  const app = join(temp, 'app');
  mkdirSync(app);
  const packageBytes = `${JSON.stringify(packageValue, null, 2)}\n`;
  writeFileSync(join(app, 'package.json'), packageBytes);
  return { temp, app, packageBytes };
}

test('dry run previews desktop setup without writing to the project', () => {
  const { temp, app, packageBytes } = fixture({
    name: 'existing-desktop',
    dependencies: { react: '^19.0.0' },
  });
  try {
    const result = adopt(app, { source: ROOT, dryRun: true });
    expect(result.template).toBe('desktop');
    expect(result.changes.some(item => item.includes('vendor/garden'))).toBe(true);
    expect(result.changes.some(item => item.includes('pinned react'))).toBe(true);
    expect(readFileSync(join(app, 'package.json'), 'utf8')).toBe(packageBytes);
    expect(existsSync(join(app, 'garden.json'))).toBe(false);
    expect(existsSync(join(app, 'vendor'))).toBe(false);
  } finally {
    rmSync(temp, { recursive: true, force: true });
  }
});

test('service adoption preserves project files and is idempotent without resnapshotting drift', () => {
  const localInstructions = Buffer.from('Keep the local launch workflow.\n');
  const oldAgents = Buffer.from('## Existing agent rules\nKeep these exactly.');
  const packageValue = {
    name: 'existing-service',
    private: true,
    packageManager: 'bun@1.3.0',
    workspaces: { packages: ['packages/*'], nohoist: ['legacy/*'] },
    scripts: { build: 'custom-build', 'garden:sync': 'custom-sync' },
    dependencies: { '@garden/daemon-kit': 'file:../daemon-kit' },
    customProductField: { owner: 'product-team' },
  };
  const { temp, app } = fixture(packageValue);
  try {
    mkdirSync(join(app, 'src'), { recursive: true });
    writeFileSync(join(app, 'src/index.ts'), 'export const existing = true;\n');
    writeFileSync(join(app, 'README.md'), 'Product README stays byte stable.\n');
    writeFileSync(join(app, 'AGENTS.md'), oldAgents);
    writeFileSync(join(app, 'AGENTS.local.md'), localInstructions);

    const result = adopt(app, { source: ROOT });
    expect(result.template).toBe('service');
    expect(result.alreadyAdopted).toBeUndefined();
    expect(existsSync(join(app, 'garden.json'))).toBe(true);
    expect(existsSync(join(app, 'garden.lock.json'))).toBe(true);
    expect(existsSync(join(app, 'docs/migrations/garden-adoption.md'))).toBe(true);
    expect(readFileSync(join(app, 'README.md'), 'utf8')).toBe('Product README stays byte stable.\n');
    expect(readFileSync(join(app, 'src/index.ts'), 'utf8')).toBe('export const existing = true;\n');
    const localAfter = readFileSync(join(app, 'AGENTS.local.md'));
    expect(localAfter.subarray(0, localInstructions.length)).toEqual(localInstructions);
    expect(localAfter.includes(oldAgents)).toBe(true);
    expect(readFileSync(join(app, 'AGENTS.md'), 'utf8')).toContain('Generated by garden sync. DO NOT EDIT.');

    const merged = JSON.parse(readFileSync(join(app, 'package.json'), 'utf8'));
    expect(merged.workspaces.packages).toEqual(['packages/*', 'vendor/garden/packages/*']);
    expect(merged.workspaces.nohoist).toEqual(['legacy/*']);
    expect(merged.dependencies['@garden/daemon-kit']).toBe('workspace:*');
    expect(merged.customProductField).toEqual({ owner: 'product-team' });
    expect(merged.scripts.build).toBe('custom-build');
    expect(merged.scripts['garden:sync']).toBe('custom-sync');
    expect(merged.scripts['garden:sync:framework']).toContain('vendor/garden/cli/garden.mjs sync');
    expect(merged.scripts['garden:doctor']).toContain('vendor/garden/cli/garden.mjs doctor');

    const lockBefore = readFileSync(join(app, 'garden.lock.json'));
    const managedFile = join(app, 'vendor/garden/contracts/framework/README.md');
    writeFileSync(managedFile, 'manual edit that must not be snapshotted away');
    const drift = readFileSync(managedFile);
    const second = adopt(app, { source: ROOT });
    expect(second.alreadyAdopted).toBe(true);
    expect(second.changes).toEqual([]);
    expect(second.remaining.some(item => item.includes('Managed file drift'))).toBe(true);
    expect(readFileSync(managedFile)).toEqual(drift);
    expect(readFileSync(join(app, 'garden.lock.json'))).toEqual(lockBefore);
  } finally {
    rmSync(temp, { recursive: true, force: true });
  }
});

test('desktop setup pins shared dependencies and records incomplete native configuration', () => {
  const { temp, app } = fixture({
    name: 'existing-desktop',
    packageManager: 'bun@1.3.0',
    dependencies: { react: '^18.2.0', 'react-dom': '^18.2.0' },
  });
  try {
    const result = adopt(app, { source: ROOT });
    expect(result.template).toBe('desktop');
    expect(result.changes.some(item => item.includes('pinned react ^18.2.0 → 19.3.0'))).toBe(true);
    expect(result.changes.some(item => item.includes('pinned packageManager bun@1.3.0 → bun@1.4.2'))).toBe(true);
    const pkg = JSON.parse(readFileSync(join(app, 'package.json'), 'utf8'));
    expect(pkg.dependencies.react).toBe('19.3.0');
    expect(pkg.dependencies['react-dom']).toBe('19.3.0');
    expect(pkg.devDependencies['@tauri-apps/cli']).toBe('2.12.0');
    expect(result.remaining.some(item => item.includes('stack.desktop requires a Rust Cargo manifest'))).toBe(true);
    const note = readFileSync(join(app, 'docs/migrations/garden-adoption.md'), 'utf8');
    expect(note).toContain('does not claim that the existing application has been migrated');
    expect(note).toContain('stack.desktop requires a Rust Cargo manifest');
  } finally {
    rmSync(temp, { recursive: true, force: true });
  }
});

test('malformed packages and unrelated Garden collisions fail before changing files', () => {
  const malformed = fixture({ name: 'bad-package', dependencies: [] });
  const manifestCollision = fixture({ name: 'unrelated-project' });
  const vendorCollision = fixture({ name: 'other-vendor' });
  try {
    expect(() => adopt(malformed.app, { source: ROOT, template: 'service' })).toThrow('package.json.dependencies');
    expect(existsSync(join(malformed.app, 'vendor'))).toBe(false);

    writeFileSync(join(manifestCollision.app, 'garden.json'), '{"project":"unrelated"}\n');
    expect(() => adopt(manifestCollision.app, { source: ROOT })).toThrow('garden.json exists but is unrelated');

    mkdirSync(join(vendorCollision.app, 'vendor/garden'), { recursive: true });
    writeFileSync(join(vendorCollision.app, 'vendor/garden/keep.txt'), 'do not replace');
    expect(() => adopt(vendorCollision.app, { source: ROOT, template: 'service' })).toThrow('vendor/garden already exists');
    expect(readFileSync(join(vendorCollision.app, 'vendor/garden/keep.txt'), 'utf8')).toBe('do not replace');
  } finally {
    for (const temp of [malformed.temp, manifestCollision.temp, vendorCollision.temp]) rmSync(temp, { recursive: true, force: true });
  }
});

test('symlinked vendor and documentation paths are rejected before writes', () => {
  const vendorFixture = fixture({ name: 'service', packageManager: 'bun@1.4.2' });
  const docsFixture = fixture({ name: 'service', packageManager: 'bun@1.4.2' });
  const outside = mkdtempSync(join(tmpdir(), 'garden-adopt-outside-'));
  try {
    mkdirSync(join(outside, 'garden'));
    writeFileSync(join(outside, 'garden/keep.txt'), 'outside data');
    symlinkSync(outside, join(vendorFixture.app, 'vendor'));
    expect(() => adopt(vendorFixture.app, { source: ROOT, template: 'service' })).toThrow('symlink');
    expect(existsSync(join(vendorFixture.app, 'garden.json'))).toBe(false);
    expect(readFileSync(join(outside, 'garden/keep.txt'), 'utf8')).toBe('outside data');

    symlinkSync(outside, join(docsFixture.app, 'docs'));
    expect(() => adopt(docsFixture.app, { source: ROOT, template: 'service' })).toThrow('symlink');
    expect(existsSync(join(docsFixture.app, 'garden.json'))).toBe(false);
  } finally {
    rmSync(vendorFixture.temp, { recursive: true, force: true });
    rmSync(docsFixture.temp, { recursive: true, force: true });
    rmSync(outside, { recursive: true, force: true });
  }
});

test('operational sync failure rolls back every project file touched by adoption', () => {
  const { temp, app, packageBytes } = fixture({
    name: 'rollback-service',
    packageManager: 'bun@1.4.2',
    scripts: { build: 'preserve-me' },
  });
  const source = join(temp, 'broken-framework');
  const oldAgents = Buffer.from('local agent instructions');
  try {
    writeFileSync(join(app, 'AGENTS.md'), oldAgents);
    copySnapshot(ROOT, source);
    writeFileSync(join(source, 'scripts/build-tokens.mjs'), 'process.exit(1);\n');

    expect(() => adopt(app, { source, template: 'service' })).toThrow('Token generation failed');
    expect(readFileSync(join(app, 'package.json'), 'utf8')).toBe(packageBytes);
    expect(readFileSync(join(app, 'AGENTS.md'))).toEqual(oldAgents);
    expect(existsSync(join(app, 'AGENTS.local.md'))).toBe(false);
    expect(existsSync(join(app, 'garden.json'))).toBe(false);
    expect(existsSync(join(app, 'garden.lock.json'))).toBe(false);
    expect(existsSync(join(app, 'vendor/garden'))).toBe(false);
    expect(existsSync(join(app, 'docs'))).toBe(false);
  } finally {
    rmSync(temp, { recursive: true, force: true });
  }
});
